const responses = $input.all().map((i) => i.json);
const source = $('Collect video links').all().map((i) => i.json);
const videos = [];
const failures = [];
for (let i = 0; i < responses.length; i += 1) {
  const res = responses[i] || {};
  const item = source[i] || {};
  const headers = res.headers || {};
  const statusCode = Number(res.statusCode || 0);
  const fileSize = Number(headers['content-length'] || headers['Content-Length'] || 0);
  const mimeType = String(headers['content-type'] || headers['Content-Type'] || 'video/mp4').split(';')[0].trim();
  if (statusCode < 200 || statusCode >= 300 || !fileSize) {
    failures.push({ productId: item.productId, title: item.title, videoUrl: item.videoUrl, errors: ['Could not read the rendered video byte size (HTTP ' + statusCode + ')'] });
    continue;
  }
  videos.push({ ...item, videoFileSize: String(fileSize), videoMimeType: mimeType || 'video/mp4', videoFilename: ('zvid-' + item.jobId + '.mp4').slice(0, 255) });
}
if (!videos.length) throw new Error('No rendered video could be prepared for Shopify staging: ' + JSON.stringify(failures).slice(0, 1200));
return videos.map((video) => ({ json: { ...video, publishFailures: failures } }));

const responses = $input.all().map((i) => i.json);
const source = $('Check Zvid video headers').all().map((i) => i.json);
const prepared = [];
const failures = source[0] && Array.isArray(source[0].publishFailures) ? [...source[0].publishFailures] : [];
for (let i = 0; i < responses.length; i += 1) {
  const res = responses[i] || {};
  const body = res.body === undefined ? res : res.body;
  const item = source[i] || {};
  const topErrors = Array.isArray(body.errors) ? body.errors.map((e) => e.message) : [];
  const payload = body.data && body.data.stagedUploadsCreate;
  const userErrors = payload && Array.isArray(payload.userErrors) ? payload.userErrors.map((e) => e.message) : [];
  const target = payload && Array.isArray(payload.stagedTargets) ? payload.stagedTargets[0] : null;
  const parameters = target && Array.isArray(target.parameters) ? Object.fromEntries(target.parameters.map((parameter) => [parameter.name, parameter.value])) : {};
  const errors = [...topErrors, ...userErrors];
  const required = ['GoogleAccessId', 'key', 'policy', 'signature'];
  if (Number(res.statusCode || 200) !== 200 || errors.length || !target || !target.url || !target.resourceUrl || required.some((name) => !parameters[name])) {
    failures.push({ productId: item.productId, title: item.title, videoUrl: item.videoUrl, errors: errors.length ? errors : ['Shopify returned an incomplete staged upload target'] });
    continue;
  }
  prepared.push({ ...item, stagedUploadUrl: target.url, stagedResourceUrl: target.resourceUrl, stagedParameters: parameters });
}
if (!prepared.length) throw new Error('Shopify could not create any staged video upload target: ' + JSON.stringify(failures).slice(0, 1200));
return prepared.map((item) => ({ json: { ...item, publishFailures: failures } }));

const responses = $input.all().map((i) => i.json);
const source = $('Check Shopify upload targets').all().map((i) => i.json);
const uploaded = [];
const failures = source[0] && Array.isArray(source[0].publishFailures) ? [...source[0].publishFailures] : [];
for (let i = 0; i < responses.length; i += 1) {
  const res = responses[i] || {};
  const item = source[i] || {};
  const statusCode = Number(res.statusCode || 0);
  if (statusCode < 200 || statusCode >= 300) {
    failures.push({ productId: item.productId, title: item.title, videoUrl: item.videoUrl, errors: ['Shopify staged upload failed with HTTP ' + statusCode] });
    continue;
  }
  uploaded.push(item);
}
if (!uploaded.length) throw new Error('No video reached Shopify staging: ' + JSON.stringify(failures).slice(0, 1200));
return uploaded.map((item) => ({ json: { ...item, publishFailures: failures } }));

