// Convert Shopify GraphQL products into Zvid bulk-template rows. The catalog
// copy and swatches come directly from the merchant's current product data.
const cfg = $('Config').first().json;
const res = $input.first().json || {};
const status = Number(res.statusCode);
const body = res.body === undefined ? res : res.body;

if (!Number.isFinite(status) || status <= 0) {
  throw new Error('Shopify did not return an HTTP response. Check shopDomain and the Shopify Header Auth credential.');
}
if (status !== 200) {
  throw new Error('Shopify catalog query failed (HTTP ' + status + '): ' + JSON.stringify(body).slice(0, 700));
}
if (Array.isArray(body.errors) && body.errors.length) {
  throw new Error('Shopify GraphQL error: ' + body.errors.map((e) => e.message).join('; '));
}

const data = body.data || {};
const shop = data.shop || {};
const connection = data.products || {};
const products = Array.isArray(connection.nodes) ? connection.nodes : [];
const clean = (value) => String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
const decodeHtml = (value) => String(value == null ? '' : value)
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#(?:39|x27);/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)));
const stripHtml = (value) => clean(decodeHtml(String(value || '').replace(/<[^>]*>/g, ' ')));
const trim = (value, max) => {
  const text = clean(value);
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  const at = cut.lastIndexOf(' ');
  return (at > max * 0.55 ? cut.slice(0, at) : cut).replace(/[\s,;:.—-]+$/, '') + '…';
};
const currency = clean(shop.currencyCode) || 'USD';
const displayMoney = (value) => {
  const amount = Number(value);
  if (!Number.isFinite(amount)) return clean(value);
  try {
    return new Intl.NumberFormat('en', {
      style: 'currency',
      currency,
      minimumFractionDigits: Number.isInteger(amount) ? 0 : 2,
      maximumFractionDigits: 2,
    }).format(amount);
  } catch {
    return (cfg.currencySymbol || '$') + amount.toFixed(2);
  }
};
const storefront = clean(shop.primaryDomain && shop.primaryDomain.url).replace(/\/+$/, '');

const paletteFor = (product) => {
  const search = clean([product.title, ...(Array.isArray(product.tags) ? product.tags : [])].join(' ')).toLowerCase();
  const palettes = [
    { terms: ['terracotta', 'clay'], label: 'Terracotta', accent: '#A85F45', tint: '#E7D6CC', accentText: '#F5F0E8' },
    { terms: ['navy', 'breton', 'harbor'], label: 'Navy & Ivory', accent: '#28374F', tint: '#DCE1E6', accentText: '#F5F0E8' },
    { terms: ['sage', 'meadow'], label: 'Sage', accent: '#6F7D66', tint: '#DEE4D9', accentText: '#F5F0E8' },
    { terms: ['washed black', 'dawnline'], label: 'Washed Black', accent: '#444541', tint: '#D9D7D1', accentText: '#F5F0E8' },
    { terms: ['ivory', 'alpine'], label: 'Warm Ivory', accent: '#B9AA8D', tint: '#EAE2D4', accentText: '#1C1D1D' },
  ];
  return palettes.find((entry) => entry.terms.some((term) => search.includes(term))) || {
    label: 'Everyday Essential',
    accent: cfg.accentColor || '#A85F45',
    tint: cfg.accentSoft || '#E7D6CC',
    accentText: cfg.paperColor || '#F5F0E8',
  };
};

const rows = [];
const skipped = [];
for (const product of products) {
  const title = clean(product.title);
  const media = [
    ...((product.hostedVideos && Array.isArray(product.hostedVideos.nodes)) ? product.hostedVideos.nodes : []),
    ...((product.externalVideos && Array.isArray(product.externalVideos.nodes)) ? product.externalVideos.nodes : []),
  ];
  const hasVideo = media.some((item) =>
    ['VIDEO', 'EXTERNAL_VIDEO'].includes(String(item.mediaContentType || '').toUpperCase()) &&
    String(item.status || '').toUpperCase() !== 'FAILED'
  );
  const imageConnection = product.productImages || product.images || {};
  const images = Array.isArray(imageConnection.nodes)
    ? imageConnection.nodes
      .map((item) => clean(item && ((item.image && item.image.url) || item.url)))
      .filter((url) => /^https?:\/\//i.test(url))
    : [];
  const variants = product.variants && Array.isArray(product.variants.nodes) ? product.variants.nodes : [];
  const variant = variants[0] || null;
  let reason = null;
  if (hasVideo) reason = 'already has Shopify video media';
  else if (!title) reason = 'missing title';
  else if (!images.length) reason = 'missing a public product image';
  else if (!variant || clean(variant.price) === '') reason = 'missing a priced variant';
  if (reason) {
    skipped.push({ productId: product.id, product: title || '(untitled)', reason });
    continue;
  }

  const descriptionHtml = String(product.descriptionHtml || '');
  const listFeatures = [...descriptionHtml.matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/gi)]
    .map((match) => trim(stripHtml(match[1]), 72))
    .filter(Boolean);
  const description = trim(product.description, 72);
  const vendor = trim(product.vendor, 50);
  const productType = trim(product.productType, 50);
  const fallbacks = [
    description || 'Designed as an easy everyday layer.',
    productType ? `${productType} by ${vendor || cfg.brandName}` : `Made by ${vendor || cfg.brandName}`,
    'Made for repeat wear.',
  ];
  const features = [0, 1, 2].map((index) => listFeatures[index] || fallbacks[index]);
  const sizes = [];
  for (const optionVariant of variants) {
    const options = Array.isArray(optionVariant.selectedOptions) ? optionVariant.selectedOptions : [];
    const sizeOption = options.find((option) => clean(option.name).toLowerCase() === 'size');
    const size = clean(sizeOption ? sizeOption.value : optionVariant.title);
    if (size && size.toLowerCase() !== 'default title' && !sizes.includes(size)) sizes.push(size);
  }
  const palette = paletteFor(product);

  rows.push({
    Product: title,
    Price: displayMoney(variant.price),
    CompareAtPrice: variant.compareAtPrice ? displayMoney(variant.compareAtPrice) : '',
    Feature1: features[0],
    Feature2: features[1],
    Feature3: features[2],
    ImageUrl1: images[0],
    ImageUrl2: images[1] || images[0],
    ImageUrl3: images[2] || images[1] || images[0],
    ImageUrl4: images[3] || images[1] || images[0],
    CtaText: cfg.ctaFallback || 'Explore the fit',
    SizeLine: sizes.length ? `Sizes ${sizes.join(' · ')}` : 'Available now',
    MetaLine: [vendor || cfg.brandName, productType].filter(Boolean).join(' · '),
    ColorLabel: palette.label,
    ProductAccent: palette.accent,
    ProductTint: palette.tint,
    AccentText: palette.accentText,
    VideoUrl: '',
    rowNumber: null,
    shopifyProductId: product.id,
    handle: clean(product.handle),
    productUrl: storefront && product.handle ? storefront + '/products/' + product.handle : null,
  });
}

const max = Math.max(1, Number(cfg.maxProducts || 5));
const selected = rows.slice(0, max);
return [{ json: {
  found: selected.length > 0,
  rows: selected,
  skipped,
  totalRowsRead: products.length,
  leftForNextRun: Math.max(0, rows.length - selected.length),
  moreCatalogPages: Boolean(connection.pageInfo && connection.pageInfo.hasNextPage),
  shop: { name: shop.name, currencyCode: currency, storefront },
  reason: selected.length ? null : 'No eligible product without video was found in this catalog scan.',
} }];

const scan = $('Rows needing videos').first().json;
return [{ json: {
  rendered: false,
  reason: scan.reason,
  productsScanned: scan.totalRowsRead,
  skipped: scan.skipped,
  hint: scan.moreCatalogPages
    ? 'This scan reached scanLimit. Raise it up to 250 or narrow shopifyProductQuery if older eligible products exist.'
    : 'The visible catalog is already covered, or products need a title, price, and image.',
} }];

// Build one shared Zvid fashion template plus one variable set per Shopify
// product. Square catalog imagery is preserved in editorial cards instead of
// being stretched into a full-screen vertical crop.
const cfg = $('Config').first().json;
const picked = $('Rows needing videos').first().json;

const esc = (value) => String(value ?? '').replace(
  /[&<>"]/g,
  (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]
);
const asMoneyNumber = (value) => {
  const match = String(value ?? '').replace(/[^0-9.]/g, '');
  const amount = parseFloat(match);
  return Number.isFinite(amount) ? amount : null;
};
const formatMoney = (amount, symbol) => {
  const rounded = Math.round(amount * 100) / 100;
  return `${symbol}${Number.isInteger(rounded) ? rounded : rounded.toFixed(2)}`;
};
const displayPrice = (value, symbol) => {
  const text = String(value ?? '').trim();
  if (!text) return '';
  return /^[0-9]/.test(text) ? `${symbol}${text}` : text;
};
const nameSizeFor = (name) => {
  const length = String(name).length;
  if (length <= 24) return 78;
  if (length <= 42) return 68;
  if (length <= 58) return 60;
  return 52;
};
const featureSizeFor = (features) => {
  const length = Math.max(...features.map((feature) => String(feature).length));
  if (length <= 38) return 34;
  if (length <= 58) return 31;
  return 28;
};
const slugify = (value) => String(value)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60) || 'product';

function buildPayload(config) {
  const paper = config.paperColor || '#F5F0E8';
  const ink = config.inkColor || '#1C1D1D';
  const muted = config.mutedColor || '#746F68';
  const line = config.lineColor || '#C9BDAE';
  const font = config.font || 'Archivo';
  const serif = config.serifFont || 'Fraunces';
  const heroSeconds = Number(config.heroSeconds ?? 4.2);
  const featureSeconds = Number(config.featureSeconds ?? 5.2);
  const ctaSeconds = Number(config.ctaSeconds ?? 4.2);
  const transitionSeconds = Number(config.transitionSeconds ?? 0.5);
  const brand = esc(config.brandName || 'Zvid Studio');
  const website = esc(config.website || 'zvid-2.myshopify.com');
  const kicker = esc(config.kicker || 'THE EVERYDAY EDIT');
