  const dealKicker = esc(config.dealKicker || 'YOUR NEXT UNIFORM');
  const tagline = esc(config.tagline || 'Quiet staples. Built with intention.');
  const rgba = (hex, alpha) => {
    const raw = String(hex).replace('#', '');
    const number = parseInt(raw.length === 3 ? raw.split('').map((char) => char + char).join('') : raw, 16);
    return `rgba(${(number >> 16) & 255},${(number >> 8) & 255},${number & 255},${alpha})`;
  };

  const heroBackground =
