    `<rect x='650' y='444' width='390' height='390' rx='30' fill='{{accent}}' fill-opacity='0.18'/>` +
    `<path d='M70 896 H1010' stroke='{{accent}}' stroke-width='5'/>` +
    `<path d='M70 1768 H1010' stroke='${line}' stroke-width='2'/>` +
    `</svg>`;
  const featureRow = (index, variable) =>
