      },
      {
        type: 'TEXT', x: 88, y: 940, width: 904, anchor: 'top-left', track: 4,
        enterBegin: 0.55, enterEnd: 1, enterAnimation: 'smoothup', exitEnd: featureSeconds,
        style: { fontFamily: font, color: ink },
