function buildItemVariables(config, row) {
  const symbol = config.currencySymbol || '$';
  const product = String(row.Product || '').trim();
  const features = [row.Feature1, row.Feature2, row.Feature3].map((value) => String(value || '').trim());
  const price = displayPrice(row.Price, symbol);
  const compareAt = displayPrice(row.CompareAtPrice, symbol);
  const priceNumber = asMoneyNumber(row.Price);
  const compareNumber = asMoneyNumber(row.CompareAtPrice);
  const showCompare = Boolean(compareAt && priceNumber != null && compareNumber != null && compareNumber > priceNumber);
  const image1 = String(row.ImageUrl1 || '').trim();
  const image2 = String(row.ImageUrl2 || '').trim() || image1;
  const image3 = String(row.ImageUrl3 || '').trim() || image2;
  const image4 = String(row.ImageUrl4 || '').trim() || image2;
  return {
    product: esc(product),
    nameSize: nameSizeFor(product),
    price: esc(price),
    compareAt: esc(compareAt),
    showCompare,
    showSingle: !showCompare,
    savingsLine: showCompare ? esc(`You save ${formatMoney(compareNumber - priceNumber, symbol)}`) : '',
    img1: image1, img2: image2, img3: image3, img4: image4,
    cta: esc(String(row.CtaText || '').trim() || config.ctaFallback || 'Explore the fit'),
    featureSize: featureSizeFor(features),
    f1: esc(features[0]), f2: esc(features[1]), f3: esc(features[2]),
    sizes: esc(row.SizeLine || 'Available now'),
    meta: esc(row.MetaLine || config.brandName || 'Zvid Studio'),
    colorLabel: esc(row.ColorLabel || 'Everyday Essential'),
    accent: String(row.ProductAccent || config.accentColor || '#A85F45'),
    tint: String(row.ProductTint || config.accentSoft || '#E7D6CC'),
    accentText: String(row.AccentText || config.paperColor || '#F5F0E8'),
  };
}

function buildProject(config, rows) {
  if (!Array.isArray(rows) || rows.length === 0) throw new Error('buildProject needs at least one catalog row.');
  const payload = buildPayload(config);
  const items = rows.map((row, index) => ({
    variables: buildItemVariables(config, row),
    name: `${slugify(row.Product)}-r${row.rowNumber ?? index + 1}`,
  }));
  const meta = {
    products: rows.map((row, index) => ({
      index, rowNumber: row.rowNumber ?? null, product: String(row.Product || '').trim(),
      shopifyProductId: row.shopifyProductId || null, handle: row.handle || null,
      productUrl: row.productUrl || null,
    })),
    sceneSeconds: payload.scenes.map((scene) => scene.duration),
    approxVideoSeconds: Math.round((
      payload.scenes.reduce((sum, scene) => sum + scene.duration, 0) -
      payload.scenes.reduce((sum, scene) => sum + (scene.transitionDuration || 0), 0)
    ) * 100) / 100,
  };
  return { payload, items, meta };
}

const { payload, items, meta } = buildProject(cfg, picked.rows);
return [{ json: { payload, items, meta: {
  ...meta, skipped: picked.skipped, leftForNextRun: picked.leftForNextRun,
  totalRowsRead: picked.totalRowsRead,
} } }];

// The free validate endpoint runs the exact resolve+validate pipeline a bulk
// item runs (first row's variables against the shared payload), so a failure
// here is a payload/data bug — surface the field list, not a generic HTTP
// error. It also returns the per-video credit price, which multiplied by the
// row count is the whole catalog's exact cost.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
const perVideo = Number(body.creditsRequired) || 0;
return [{
  json: {
    ...build,
    creditsPerVideo: perVideo,
    totalCredits: perVideo * build.items.length,
    warnings: body.warnings || [],
    resolvedFirst: body.payload,
    schemaVersion: body.schemaVersion,
  },
}];

// Free review gate: validates the whole design, quotes the full batch and
// saves the first resolved product as a Zvid editor draft.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;
let editorLink = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) editorLink = String(cfg.editorUrl).replace(/\/+$/, '') + '/?project=' + project.id;
} catch {}
return [{ json: {
  dryRun: true,
  videosPlanned: d.items.length,
  productsToRender: d.meta.products.map((p) => ({ productId: p.shopifyProductId, title: p.product, productUrl: p.productUrl })),
  creditsPerVideo: d.creditsPerVideo,
  totalCredits: d.totalCredits,
  approxSecondsPerVideo: d.meta.approxVideoSeconds,
  skipped: d.meta.skipped,
  warnings: d.warnings,
  editorLink,
  nextStep: 'Review editorLink, then set dryRun to false. Keep publishToShopify false for rendered review links, or set it true to attach accepted videos to the matching Shopify products.',
} }];

// HTTP 202 means the batch is queued. Individual items can still be rejected
// at submit time (validation is best-effort per item) — map those back to
// Shopify products so the summary can name them. Job names stay NULL until a job
// completes, so results are mapped by jobId → submit index → row, never by
// name.
const res = $input.first().json;
const build = $('Check validation').first().json;

if (!res || !res.bulkId) {
  throw new Error('Bulk submit returned no bulkId: ' + JSON.stringify(res).slice(0, 400));
}

const jobIndexById = {};
for (const j of res.jobs || []) jobIndexById[j.jobId] = j.index;

const rejected = (res.errors || []).map((e) => {
  const p = build.meta.products[e.item] || {};
  return { productId: p.shopifyProductId, product: p.product, error: e.error, details: e.details };
});

return [{
  json: {
    bulkId: res.bulkId,
    totalJobs: res.totalJobs,
    creditsReserved: res.creditsReserved,
    queueAhead: res.queueAhead,
    jobIndexById,
    rejected,
  },
}];

// Fails fast when the whole batch failed, and stops the poll loop at
// timeoutMinutes. A timeout does NOT cancel the renders — they finish on
// Zvid's side (see https://app.zvid.io); raise timeoutMinutes for bigger
// catalogs rather than re-running immediately.
const cfg = $('Config').first().json;
const poll = $input.first().json;
const b = poll.bulk || {};
const c = b.counts || {};

if (b.status === 'failed') {
  const firstError = (poll.jobs || []).map((j) => j.errorMessage).filter(Boolean)[0];
  throw new Error('Every job in bulk ' + b.id + ' failed. First error: ' + (firstError || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(
    'Bulk ' + b.id + ' did not finish within ' + cfg.timeoutMinutes + ' minutes (' +
    (c.completed || 0) + '/' + b.totalJobs + ' done, ' + (c.pending || 0) + ' still rendering). ' +
    'The remaining renders continue on Zvid\'s side — check https://app.zvid.io before re-running, or raise timeoutMinutes.'
  );
}

return $input.all();

// Maps Zvid jobs back to Shopify product GIDs by the submit-time job index.
const poll = $input.first().json;
const sub = $('Check batch accepted').first().json;
const build = $('Check validation').first().json;
const bulk = poll.bulk || {};
const completed = [];
const failures = [];
for (const job of poll.jobs || []) {
  const index = sub.jobIndexById[job.id];
  const product = index == null ? null : build.meta.products[index];
  if (!product) continue;
  if (job.status === 'completed' && job.outputUrl) {
    completed.push({
      productId: product.shopifyProductId,
      title: product.product,
      handle: product.handle,
      productUrl: product.productUrl,
      videoUrl: job.outputUrl,
      jobId: job.id,
      creditsUsed: Number(job.creditsConsumed) || null,
    });
  } else {
    failures.push({ productId: product.shopifyProductId, title: product.product, status: job.status, error: job.errorMessage || null });
  }
}
if (!completed.length) throw new Error('Bulk ' + bulk.id + ' finished without a video URL. ' + JSON.stringify(failures).slice(0, 700));
return completed.map((item) => ({ json: { ...item, renderFailures: failures } }));

const videos = $input.all().map((i) => i.json);
return [{ json: {
  rendered: videos.length,
  publishedToShopify: false,
  creditsSpent: videos.reduce((sum, v) => sum + (Number(v.creditsUsed) || 0), 0),
  videos: videos.map((v) => ({ productId: v.productId, title: v.title, productUrl: v.productUrl, videoUrl: v.videoUrl })),
  renderFailures: videos[0] ? videos[0].renderFailures : [],
  nextStep: 'Review the video URLs. To publish automatically on the next catalog batch, set publishToShopify to true in Config.',
} }];

// The staged upload has completed before this mutation runs. Confirm the
// product association; failed products are never tagged and stay eligible for retry.
const responses = $input.all().map((i) => i.json);
const source = $('Check Shopify staged uploads').all().map((i) => i.json);
const successes = [];
const failures = source[0] && Array.isArray(source[0].publishFailures) ? [...source[0].publishFailures] : [];
for (let i = 0; i < responses.length; i += 1) {
  const res = responses[i] || {};
  const body = res.body === undefined ? res : res.body;
  const item = source[i] || {};
  const topErrors = Array.isArray(body.errors) ? body.errors.map((e) => e.message) : [];
  const payload = body.data && body.data.productUpdate;
  const userErrors = payload && Array.isArray(payload.userErrors) ? payload.userErrors.map((e) => e.message) : [];
  const errors = [...topErrors, ...userErrors];
  if (Number(res.statusCode || 200) !== 200 || errors.length || !payload || !payload.product) {
    failures.push({ productId: item.productId, title: item.title, videoUrl: item.videoUrl, stagedResourceUrl: item.stagedResourceUrl, errors: errors.length ? errors : ['Shopify returned no updated product'] });
    continue;
  }
  successes.push({ ...item, shopifyMediaId: null, shopifyMediaStatus: 'PROCESSING' });
}
if (!successes.length) throw new Error('Shopify rejected every staged product-video association: ' + JSON.stringify(failures).slice(0, 1200));
return successes.map((item) => ({ json: { ...item, publishFailures: failures } }));

const published = $('Check Shopify publish requests').all().map((i) => i.json);
const tagResponses = $input.all().map((i) => i.json);
const tagFailures = [];
for (let i = 0; i < tagResponses.length; i += 1) {
  const res = tagResponses[i] || {};
  const body = res.body === undefined ? res : res.body;
  const errors = [
    ...(Array.isArray(body.errors) ? body.errors.map((e) => e.message) : []),
    ...((body.data && body.data.tagsAdd && Array.isArray(body.data.tagsAdd.userErrors)) ? body.data.tagsAdd.userErrors.map((e) => e.message) : []),
  ];
  if (Number(res.statusCode || 200) !== 200 || errors.length) {
    tagFailures.push({ productId: published[i] && published[i].productId, errors: errors.length ? errors : ['Tag request failed'] });
  }
}
return [{ json: {
  rendered: $('Collect video links').all().length,
  acceptedByShopify: published.length,
  creditsSpent: $('Collect video links').all().reduce((sum, i) => sum + (Number(i.json.creditsUsed) || 0), 0),
  products: published.map((p) => ({ productId: p.productId, title: p.title, productUrl: p.productUrl, videoUrl: p.videoUrl, shopifyMediaId: p.shopifyMediaId, shopifyMediaStatus: p.shopifyMediaStatus })),
  renderFailures: published[0] ? published[0].renderFailures : [],
  publishFailures: published[0] ? published[0].publishFailures : [],
  tagFailures,
  note: 'Each Zvid MP4 was uploaded to Shopify staging and accepted for asynchronous processing on its matching product.',
} }];
